import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Git & Workflow — Discipline That Scales","description":"Branching strategy, review discipline, conventional commits and CI habits for solo and agent-team development.","frontmatter":{"title":"Git & Workflow — Discipline That Scales","description":"Branching strategy, review discipline, conventional commits and CI habits for solo and agent-team development."},"headers":[],"relativePath":"en/skills/git/index.md","filePath":"en/skills/git/index.md"}`),a={name:`en/skills/git/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="git-workflow-—-discipline-that-scales" tabindex="-1">Git &amp; Workflow — Discipline That Scales <a class="header-anchor" href="#git-workflow-—-discipline-that-scales" aria-label="Permalink to “Git &amp; Workflow — Discipline That Scales”">​</a></h1><p>Git is the contract between past me, future me and the agents working on my behalf. My workflow rules are simple enough to follow at 2 AM and strict enough that agent-generated diffs stay reviewable.</p><h2 id="the-rules" tabindex="-1">The rules <a class="header-anchor" href="#the-rules" aria-label="Permalink to “The rules”">​</a></h2><ul><li><strong>Small, single-purpose branches.</strong> One idea per branch — human or agent authored.</li><li><strong>Conventional commits.</strong> <code>feat:</code>, <code>fix:</code>, <code>refactor:</code> — changelogs write themselves.</li><li><strong>Review everything.</strong> Especially agent code; trust is granted per-diff, never per-tool.</li><li><strong>Main stays deployable.</strong> If <code>main</code> breaks, fixing it outranks everything else.</li><li><strong>Tags for releases.</strong> Every shipped state is retrievable forever.</li></ul><p>With agents in the loop this discipline stops being optional: three sandboxes producing diffs in parallel only works if history stays clean and each change is isolated. The <a href="/Usf/en/about/how-i-work/">agentic method</a> depends on git being boring and predictable — exactly what I want from infrastructure.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};